# Let me try: fill cells that are between markers both horizontally AND vertically
# (r,c) is filled if it's bounded horizontally by markers and vertically by markers

def fill_between(grid, marker_val):
    """Fill 0s that have markers to the left AND right, AND above AND below."""
    h, w = len(grid), len(grid[0])

    # Find min/max row and col with marker for each row/col
    markers_left_of = {}  # (r,c,h_key) -> max marker column for row r at or before col
    markers_right_of = {}
    markers_above = {}    # (r,c,v_key) -> max marker row for col c at or above row
    markers_below = {}    # (r,c,v_key) -> min marker row for col c at or below row

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_val:
                markers_left_of[(r, c, 1)] = c
                markers_below[(c, c, 1)] = r

    # Precompute left/right bounds for each cell
    def has_marker_any_horizontal_direction(r, c):
        # Check if there's a marker in the same row, before or after
        for cc in range(c + 1, w):
            if grid[r][cc] == marker_val:
                return True
        for cc in range(c - 1, -1, -1):
            if grid[r][cc] == marker_val:
                return True
        return False

    def has_marker_any_vertical_direction(r, c):
        for rr in range(r + 1, h):
            if grid[rr][c] == marker_val:
                return True
        for rr in range(r - 1, -1, -1):
            if grid[rr][c] == marker_val:
                return True
        return False

    def is_left_of_marker(r, c):
        for cc in range(c - 1, -1, -1):
            if grid[r][cc] == marker_val:
                return True
        return False

    def is_right_of_marker(r, c):
        for cc in range(c + 1, w):
            if grid[r][cc] == marker_val:
                return True
        return False

    def is_above_marker(r, c):
        for rr in range(r - 1, -1, -1):
            if grid[rr][c] == marker_val:
                return True
        return False

    def is_below_marker(r, c):
        for rr in range(r + 1, h):
            if grid[rr][c] == marker_val:
                return True
        return False

    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                # Check if surrounded horizontally and vertically
                if (is_left_of_marker(r, c) and is_right_of_marker(r, c) and
                    is_above_marker(r, c) and is_below_marker(r, c)):
                    result[r][c] = 2

    return result

print("Fill between markers:")
